mapper.select:
SELECT max(id)::text
FROM runrun_v2.fulfillment_tasks
WHERE order_id = #{orderId,jdbcType=BIGINT}

SELECT count(*)
FROM runrun_v2.v2_order_proofs
WHERE task_id = #{taskId,jdbcType=BIGINT}
    AND kind = #{kind,jdbcType=VARCHAR}

SELECT count(*)
FROM runrun_v2.v2_order_proofs
WHERE storage_key = #{storageKey,jdbcType=VARCHAR}

SELECT *
FROM runrun_v2.location_events
WHERE task_id = #{taskId,jdbcType=BIGINT}
    AND event_type = #{eventType,jdbcType=VARCHAR}
    AND request_id = #{requestId,jdbcType=VARCHAR}

SELECT count(*)
FROM runrun_v2.location_events
WHERE id = #{locationEventId,jdbcType=BIGINT}
    AND order_id = #{orderId,jdbcType=BIGINT}
    AND task_id = #{taskId,jdbcType=BIGINT}
    AND courier_id = #{actorId,jdbcType=BIGINT}
    AND event_type = 'DELIVERY'
    AND accepted
    AND deleted_at IS NULL

mapper.delete:
DELETE
FROM runrun_v2.fulfillment_completion_blocks
WHERE order_id = #{orderId,jdbcType=BIGINT}
    AND source_type = #{sourceType,jdbcType=VARCHAR}
    AND source_id = #{sourceId,jdbcType=VARCHAR}

mapper.update:
UPDATE runrun_v2.v2_orders
SET confirm_started_at = #{confirmStartedAt,jdbcType=TIMESTAMP_WITH_TIMEZONE},
    confirm_deadline = #{confirmDeadline,jdbcType=TIMESTAMP_WITH_TIMEZONE},
    version = version + 1,
    updated_at = #{updatedAt,jdbcType=TIMESTAMP_WITH_TIMEZONE}
WHERE id = #{orderId,jdbcType=BIGINT}

UPDATE runrun_v2.v2_orders
SET status = 'COMPLETED',
    completed_at = #{completedAt,jdbcType=TIMESTAMP_WITH_TIMEZONE},
    version = version + 1,
    updated_at = #{updatedAt,jdbcType=TIMESTAMP_WITH_TIMEZONE}
WHERE id = #{orderId,jdbcType=BIGINT}

mapper.select:
SELECT id::text
FROM runrun_v2.fulfillment_tasks
WHERE courier_id = #{courierId,jdbcType=BIGINT}
    AND order_id = #{orderId,jdbcType=BIGINT}
ORDER BY id DESC
LIMIT 1

SELECT *
FROM runrun_v2.fulfillment_tasks
WHERE id = #{taskId,jdbcType=BIGINT}

SELECT superseded_at IS NULL
FROM runrun_v2.fulfillment_tasks
WHERE id = #{taskId,jdbcType=BIGINT}

SELECT id = #{taskId,jdbcType=BIGINT}
FROM runrun_v2.fulfillment_tasks
WHERE order_id = #{orderId,jdbcType=BIGINT}
ORDER BY id DESC
LIMIT 1

SELECT count(*)
FROM runrun_v2.v2_order_proofs
WHERE id = #{proofId,jdbcType=BIGINT}
    AND order_id = #{orderId,jdbcType=BIGINT}
    AND task_id = #{taskId,jdbcType=BIGINT}
    AND kind = #{kind,jdbcType=VARCHAR}
    AND storage_status = 'AVAILABLE'
    AND deleted_at IS NULL

mapper.update:
UPDATE runrun_v2.fulfillment_tasks
SET superseded_at = #{supersededAt,jdbcType=TIMESTAMP_WITH_TIMEZONE},
    version = version + 1
WHERE order_id = #{orderId,jdbcType=BIGINT}
    AND id <> #{retainedTaskId,jdbcType=BIGINT}
    AND superseded_at IS NULL

